package com.nutomic.syncthingandroid.util

import com.nutomic.syncthingandroid.util.CertificateValidator.Check
import com.nutomic.syncthingandroid.util.CertificateValidator.Status
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Self-signed EC pairs generated by openssl for this test, valid until 2126.
 */
class CertificateValidatorTest {

    private fun keyStatus(cert: String, key: String): Status =
        CertificateValidator.validate(cert.toByteArray(), key.toByteArray(), osTrustManager = null)
            .checks.first { it.check == Check.KEY }.status

    @Test
    fun privateKeyIsDecodedAndMatchedAgainstTheCertificate() {
        assertEquals(Status.PASS, keyStatus(CERT_A, KEY_A))
        assertEquals(Status.FAIL, keyStatus(CERT_A, KEY_B))
    }

    @Test
    fun leafFingerprintIsTheSha256OfTheDerCertificate() {
        assertEquals("8f7c444cf29a10ae6e8537ff73122e358d61aef81707f4834f230d1220709022", CertificateValidator.leafFingerprint(CERT_A.toByteArray()))
    }

    private companion object {
        val CERT_A = """
-----BEGIN CERTIFICATE-----
MIIBjTCCATOgAwIBAgIUQqpaCccwgff9lqQhZxcRMbSMuzUwCgYIKoZIzj0EAwIw
GzEZMBcGA1UEAwwQc3luY3RoaW5nLXRlc3QtYTAgFw0yNjEwMjIyMzI0NTlaGA8y
MTI2MDkyODIzMjQ1OVowGzEZMBcGA1UEAwwQc3luY3RoaW5nLXRlc3QtYTBZMBMG
ByqGSM49AgEGCCqGSM49AwEHA0IABOxNUAmfzWgzqC9FsVcrgffqmSQcx/oWEwhL
+eE3azGAjh+GnXW7GNRiS/JywEqa/OHFRuNiwrsXFUNX3ct5YcSjUzBRMB0GA1Ud
DgQWBBSBgHNTU7xQ2YD6xle7PtY45VPD7TAfBgNVHSMEGDAWgBSBgHNTU7xQ2YD6
xle7PtY45VPD7TAPBgNVHRMBAf8EBTADAQH/MAoGCCqGSM49BAMCA0gAMEUCIBrQ
HhLULqo5RtQpaQhwP7uQ5gzpRox3H3vganx2E5MoAiEAxFdtKSQc56QeHXunaGR2
7k538zPvNqj99jmcvsCfLRM=
-----END CERTIFICATE-----
""".trimIndent()

        val KEY_A = """
